const c=document.getElementById("mobile-nav-toggle"),e=document.querySelector(".sidebar"),t=document.getElementById("mobile-backdrop");function n(){e?.classList.remove("open"),t?.classList.remove("visible")}function o(){e?.classList.add("open"),t?.classList.add("visible")}c?.addEventListener("click",()=>{e?.classList.contains("open")?n():o()});t?.addEventListener("click",n);e?.querySelectorAll("a.nav-link").forEach(s=>s.addEventListener("click",n));
